 public bool ApplyChanges(bool closeWindow=false){if(Result.Servers.Count==0){status.Text="至少保留一台服务器。";return false;}if(!Capture(true))return false;var invalid=Result.Servers.Find(server=>string.IsNullOrWhiteSpace(server.Name)||(!server.IsLocal&&(!Regex.IsMatch(server.Host??"",@"^[a-zA-Z0-9._:-]+$")||server.Port<1||server.Port>65535)));if(invalid!=null){status.Text="请补全所有服务器的连接信息。";list.SelectedItem=invalid;return false;}if(Result.Servers.GroupBy(server=>server.Name).Any(group=>group.Count()>1)){status.Text="请为每台服务器设置不同的名称。";return false;}int seconds;if(!int.TryParse(frequency.SelectedItem as string,out seconds)||seconds<2||seconds>120){status.Text="刷新间隔应为 2–120 秒。";return false;}CaptureTerminalSettings();Result.RetentionDays=int.Parse(retention.SelectedItem as string);Result.ArchiveLimitMB=int.Parse(archiveCap.SelectedItem as string);Result.Interval=seconds;Result.ThemeName=Theme.Keys[Math.Max(0,themePicker.SelectedIndex)];Result.CloseToTray=closeToTray.IsChecked==true;Result.SelectedName=current.Name;try{if(ApplyRequested!=null)ApplyRequested(Result.Copy(),StartupEnabled);Resources=Theme.Resources();Background=Theme.Bg;Foreground=Theme.Ink;PaneLayouts.RefreshTree(Root);status.Foreground=Theme.Green;status.Text="已应用";if(closeWindow)DialogResult=true;return true;}catch(Exception e){status.Foreground=Theme.Red;status.Text="应用失败，请重试。";status.ToolTip=e.Message;return false;}}
 TextBox Field(StackPanel parent,string label){parent.Children.Add(Theme.Text(label,14,Theme.Muted));var field=new TextBox{Margin=new Thickness(0,8,0,16),FontFamily=Theme.Chinese,FontSize=15,Height=40,MinHeight=40,VerticalContentAlignment=VerticalAlignment.Center};parent.Children.Add(field);return field;}
 void Reload(Server selected){loading=true;list.ItemsSource=null;list.ItemsSource=Result.Servers;list.SelectedItem=selected;loading=false;LoadServer(selected);}
 void LoadServer(Server s){connectionTicket++;if(test!=null)test.IsEnabled=true;if(status!=null){status.Text="";status.ToolTip=null;}current=s;name.Text=s==null?"":s.Name;host.Text=s==null?"":s.Host;user.Text=s==null?"":s.User;port.Text=s==null?"22":s.Port.ToString();key.Text=s==null?"":s.KeyPath;foreach(var field in new[]{host,user,port,key})field.IsEnabled=s==null||!s.IsLocal;}
 bool Capture(bool validate){if(current==null)return false;if(current.IsLocal){if(string.IsNullOrWhiteSpace(name.Text)){if(validate)status.Text="请填写设备名称。";return false;}current.Name=name.Text.Trim();return true;}int number;if(!int.TryParse(port.Text,out number)||number<1||number>65535){if(validate)status.Text="SSH 端口应为 1–65535。";return false;}if(validate&&(string.IsNullOrWhiteSpace(name.Text)||!Regex.IsMatch(host.Text.Trim(),@"^[a-zA-Z0-9._:-]+$")||!Regex.IsMatch(user.Text.Trim(),@"^[a-zA-Z0-9._-]*$"))){status.Text="请检查名称、地址和用户名。";return false;}current.Name=name.Text.Trim();current.Host=host.Text.Trim();current.User=user.Text.Trim();current.Port=number;current.KeyPath=key.Text.Trim();return true;}
 async void TestConnection(){if(!Capture(true))return;int ticket=++connectionTicket;var target=current.Copy();test.IsEnabled=false;status.Foreground=Theme.Muted;status.Text=target.IsLocal?"正在检查本机…":"正在验证 SSH 连接…";var result=await Task.Run(()=>ConnectionProbe.Run(target));if(ticket!=connectionTicket)return;status.Text=result.Message;status.ToolTip=result.Details;status.Foreground=result.Success?Theme.Green:Theme.Red;test.IsEnabled=true;}
 public void RenderImage(string path,int width,int height,int dpi){Snapshot.Save(Root,path,width,height,dpi,null);}

